#include <stdio.h>
#include <string.h>
int main(void){
    const char *p="aaaa";
    int m=(int)strlen(p);
    int next[16], nextval[16];
    next[1]=0;
    for(int j=1,k=0;j<m;){
        if(k==0 || p[j-1]==p[k-1]){ j++; k++; next[j]=k; }
        else k=next[k];
    }
    nextval[1]=0;
    for(int i=2;i<=m;i++){
        if(p[i-1]==p[next[i]-1]) nextval[i]=nextval[next[i]];
        else nextval[i]=next[i];
    }
    printf("模式串: %s\n", p);
    printf("位置  :"); for(int i=1;i<=m;i++) printf(" %d",i); printf("\n");
    printf("字符  :"); for(int i=0;i<m;i++) printf(" %c",p[i]); printf("\n");
    printf("next  :"); for(int i=1;i<=m;i++) printf(" %d",next[i]); printf("\n");
    printf("nextval:"); for(int i=1;i<=m;i++) printf(" %d",nextval[i]); printf("\n");
    printf("说明：第 i 位与回退位字符相同，则 nextval[i]=nextval[next[i]]，\n");
    printf("'aaaa' 因此全部塌缩为 0，失配时一次回退到位。\n");
    return 0;
}
